        --bg-start: #eef4ff;
        --bg-end: #f8fafc;
        --panel: rgba(255, 255, 255, 0.88);
        --panel-border: rgba(148, 163, 184, 0.24);
        --text: #0f172a;
        --muted: #475569;
        --accent: #2563eb;
        --accent-strong: #1d4ed8;
        --accent-soft: rgba(37, 99, 235, 0.1);
