        margin: 0 0 32px;
        color: var(--muted);
        font-size: 1.02rem;
        line-height: 1.65;
        max-width: 56ch;
      }

      .preference-form {
        display: grid;
        gap: 24px;
      }

      .form-field {
        border: 1px solid rgba(148, 163, 184, 0.28);
        border-radius: 22px;
        background: rgba(255, 255, 255, 0.8);
        padding: 24px;
      }

      .field-label {
        display: block;
        font-size: 1.06rem;
        font-weight: 700;
        margin-bottom: 18px;
      }

      .radio-group {
        display: grid;
        gap: 14px;
      }

      .radio-option {
        display: flex;
        align-items: center;
        gap: 14px;
        padding: 16px 18px;
        border: 1px solid rgba(148, 163, 184, 0.26);
        border-radius: 18px;
        background: #ffffff;
        transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
        cursor: pointer;
