      .option-copy {
        display: grid;
        gap: 4px;
      }

      .option-title {
        font-weight: 700;
      }

      .option-description {
        color: var(--muted);
        font-size: 0.95rem;
      }

      .form-actions {
        display: flex;
        align-items: center;
        gap: 16px;
        flex-wrap: wrap;
      }

      .submit-button {
        appearance: none;
        border: 0;
        border-radius: 14px;
        background: linear-gradient(135deg, var(--accent), #4f46e5);
        color: #ffffff;
        font: inherit;
        font-weight: 700;
        padding: 14px 22px;
        cursor: pointer;
        box-shadow: 0 16px 28px rgba(37, 99, 235, 0.24);
        transition: transform 180ms ease, box-shadow 180ms ease, filter 180ms ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 20px 34px rgba(37, 99, 235, 0.28);
        filter: brightness(1.03);
      }

      .submit-button:active {
        transform: translateY(0);
      }

      .status {
        color: var(--muted);
        font-size: 0.96rem;
      }

      @media (max-width: 640px) {
        .card-content {
          padding: 28px 20px;
        }

        .form-field {
          padding: 20px;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script type="text/babel">
      const options = [
        {
          value: "Email",
          description: "Receive updates in your inbox for easy reference."
        },
        {
          value: "SMS",
          description: "Get fast text alerts for important activity."
        },
        {
          value: "Push Notifications",
          description: "Stay informed instantly on your devices."
        }
      ];

      function Header() {
        return (
          <>
            <div className="eyebrow">Preferences</div>
            <h1>Choose your notification style</h1>
            <p className="intro">
              Tell us how you prefer to receive notifications so we can deliver updates in
              the way that works best for you.
            </p>
          </>
        );
      }

      function RadioOption({ value, description, selected, onChange }) {
        return (
          <label className="radio-option">
            <input
              type="radio"
              name="notificationPreference"
              value={value}
              checked={selected === value}
              onChange={onChange}
              required
            />
            <span className="option-copy">
              <span className="option-title">{value}</span>
              <span className="option-description">{description}</span>
            </span>
          </label>
        );
      }

      function NotificationForm() {
        const [selected, setSelected] = React.useState("");
        const [message, setMessage] = React.useState("Select one option and submit.");

        const handleSubmit = (event) => {
          event.preventDefault();
          setMessage(`Preference saved: ${selected}.`);
        };

        return (
          <form className="preference-form" onSubmit={handleSubmit}>
            <div className="form-field">
              <label className="field-label" htmlFor="notification-email">
                How do you prefer to receive notifications?
              </label>
              <div className="radio-group" role="radiogroup" aria-labelledby="notification-email">
                {options.map((option, index) => (
                  <RadioOption
                    key={option.value}
                    value={option.value}
                    description={option.description}
                    selected={selected}
                    onChange={() => setSelected(option.value)}
                    id={`notification-${index}`}
                  />
                ))}
              </div>
            </div>

            <div className="form-actions">
              <button className="submit-button" type="submit">
                Submit
              </button>
              <span className="status" aria-live="polite">
                {message}
              </span>
            </div>
          </form>
        );
      }

      function App() {
        return (
          <main className="app-shell">
            <section className="form-card">
              <div className="card-accent"></div>
              <div className="card-content">
                <Header />
                <NotificationForm />
              </div>
            </section>
          </main>
        );
      }

      const root = ReactDOM.createRoot(document.getElementById("root"));
      root.render(<App />);
    </script>
  </body>
</html>
