      ];

      function Header() {
        return (
          <>
            <div className="eyebrow">Preferences</div>
            <h1>Choose your notification style</h1>
            <p className="intro">
              Tell us how you prefer to receive notifications so we can deliver updates in
              the way that works best for you.
            </p>
          </>
        );
      }

      function RadioOption({ id, value, description, selected, onChange }) {
        return (
          <label className="radio-option">
            <input
              id={id}
              type="radio"
              name="notificationPreference"
              value={value}
              checked={selected === value}
              onChange={onChange}
              required
            />
            <span className="option-copy">
              <span className="option-title">{value}</span>
              <span className="option-description">{description}</span>
            </span>
          </label>
        );
      }

      function NotificationForm() {
        const [selected, setSelected] = React.useState("");
        const [message, setMessage] = React.useState("Select one option and submit.");

        const handleSubmit = (event) => {
          event.preventDefault();
          setMessage(`Preference saved: ${selected}.`);
        };

        return (
          <form className="preference-form" onSubmit={handleSubmit}>
            <div className="form-field">
              <div className="field-label" id="notification-question">
                How do you prefer to receive notifications?
              </div>
              <div className="radio-group" role="radiogroup" aria-labelledby="notification-question">
                {options.map((option, index) => (
                  <RadioOption
                    key={option.value}
                    id={`notification-${index}`}
                    value={option.value}
                    description={option.description}
                    selected={selected}
                    onChange={() => setSelected(option.value)}
                  />
                ))}
              </div>
            </div>

            <div className="form-actions">
              <button className="submit-button" type="submit">
                Submit
              </button>
              <span className="status" aria-live="polite">
                {message}
              </span>
            </div>
          </form>
        );
      }

      function App() {
        return (
          <main className="app-shell">
            <section className="form-card">
              <div className="card-accent"></div>
              <div className="card-content">
                <Header />
                <NotificationForm />
              </div>
            </section>
          </main>
        );
      }

      const root = ReactDOM.createRoot(document.getElementById("root"));
      root.render(<App />);
    </script>
  </body>
</html>
